#include "reg_mapping.h"

uc_arm_reg map_arm_reg_2U(arm_reg reg) {
  switch(reg) {
    case ARM_REG_CPSR:
      return UC_ARM_REG_CPSR;
    case ARM_REG_FPEXC:
      return UC_ARM_REG_FPEXC;
    case ARM_REG_LR:
      return UC_ARM_REG_LR;
    case ARM_REG_PC:
      return UC_ARM_REG_PC;
    case ARM_REG_SP:
      return UC_ARM_REG_SP;
    case ARM_REG_SPSR:
      return UC_ARM_REG_SPSR;
    case ARM_REG_R0:
      return UC_ARM_REG_R0;
    case ARM_REG_R1:
      return UC_ARM_REG_R1;
    case ARM_REG_R2:
      return UC_ARM_REG_R2;
    case ARM_REG_R3:
      return UC_ARM_REG_R3;
    case ARM_REG_R4:
      return UC_ARM_REG_R4;
    case ARM_REG_R5:
      return UC_ARM_REG_R5;
    case ARM_REG_R6:
      return UC_ARM_REG_R6;
    case ARM_REG_R7:
      return UC_ARM_REG_R7;
    case ARM_REG_R8:
      return UC_ARM_REG_R8;
    case ARM_REG_R9:
      return UC_ARM_REG_R9;
    case ARM_REG_R10:
      return UC_ARM_REG_R10;
    case ARM_REG_R11:
      return UC_ARM_REG_R11;
    case ARM_REG_R12:
      return UC_ARM_REG_R12;
    default:
      return (uc_arm_reg) reg;
  }
}

